NS="لم تنص الموسوعة في الصفحات المقروءة على قول خاص بهذا المذهب في هذه المسألة."
def pm(f,start):
    t=open(f).read();pos=[n for n,c in enumerate(t) if unicodedata.category(c)!='Mn'];pl=''.join(t[n] for n in pos)
    return t,pos[pl.index(start)]
import unicodedata as _u
def hl(n,start,cut=True):
    import unicodedata as u
    t=open('/tmp/h2/sw_bukhari_%s.txt'%n).read()
    st=''.join(c for c in start if u.category(c)!='Mn')
    for l in t.split('\n'):
        pos=[k for k,c in enumerate(l) if u.category(c)!='Mn']
        pl=''.join(l[k] for k in pos)
        if pl.strip().startswith('حدثنا') and st in pl:
            seg=l[pos[pl.index(st)]:]
            if cut: seg=seg[:seg.rfind('"')]
            return seg.replace('\u200f','').replace('  ',' ').strip()
    raise SystemExit('nohadith')
